        print('=== leaf',i,'printed~',i+540)
for i,p in enumerate(pages):
    if 'خاور' in p and ('اوستا' in p or 'پهلوی' in p or 'پپلوی' in p):
        print('--- khavar leaf',i,'printed~',i+540)
EOF

cd /home/sfmqrb/git/rishe/data/verification/sources/refs/incoming/BQT
python3 - <<'EOF'
t=open('BQT_v3_pages_faseng.txt').read()
pages=t.split('\f')
for i,p in enumerate(pages):
    if 'farr' in p or 'xvarnah' in p or 'hvarnah' in p or 'farnah' in p or 'xwarrah' in p:
        print('=== pdf page',i+1)
        for line in p.split('\n'):
            if 'farr' in line or 'arnah' in line or 'xwarr' in line:
                print('   ',line.strip()[:200])
EOF

